import {SAMPLE,LABELS,escapeHTML as esc,lines,validateInput,manualResult,money,estimate,makeBrief,makeResponse} from './core.js';
const $=s=>document.querySelector(s);
let project=structuredClone(SAMPLE),records=[],filter='all',view='review',isSample=true,worker=null,runId=0,busy=false,modelReady=false,consented=false,expanded=new Set(),modelTimer=null,responseDraft=null;
function resetRecords(){records=project.requests.map((text,i)=>({id:i,text,result:manualResult(),override:'',hours:null,notes:''}));expanded.clear();}
resetRecords();
function status(text){$('#live-status').textContent=text;}
function toast(text){document.querySelector('.toast')?.remove();const el=document.createElement('div');el.className='toast';el.role='status';el.textContent=text;document.body.append(el);setTimeout(()=>el.remove(),3500);}
function render(){
 $('#project-title').textContent=project.title||'Untitled project';$('#sidebar-title').textContent=project.title||'Untitled project';$('#scope-count').textContent=`${project.scope.length} agreed scope item${project.scope.length===1?'':'s'}`;
 const reviewed=records.filter(r=>r.override||r.result.source!=='manual').length;
 $('#request-count').innerHTML=`${String(records.length).padStart(2,'0')} <span>${reviewed}/${records.length} reviewed</span>`;$('.nav-count').textContent=records.length;
 $('#total-estimate').textContent=money(estimate(records,project.rate),project.currency);
 $('#estimate-caption').textContent=records.some(r=>(r.override||r.result.label)==='change'&&r.hours===null)?'Incomplete · add your hours':'Your entered hours × rate, excl. tax';
 $('#all-count').textContent=records.length;$('#changes-count').textContent=records.filter(r=>(r.override||r.result.label)==='change').length;$('#clarify-count').textContent=records.filter(r=>(r.override||r.result.label)==='clarify').length;
 $('#sample-note').hidden=!isSample;$('#scope-list').innerHTML=project.scope.map((s,i)=>`<li><span>S${String(i+1).padStart(2,'0')}</span>${esc(s)}</li>`).join('')||'<li>Add your agreed scope to begin.</li>';
 const visible=records.filter(r=>filter==='all'||(r.override||r.result.label)===filter);
 $('#request-list').innerHTML=visible.length?visible.map(card).join(''):'<div class="empty-state"><strong>A little breathing room.</strong>No requests in this view.</div>';
 $('#brief-output').textContent=makeBrief(project,records);$('#response-output').value=responseDraft??makeResponse(project,records);
 $('#review-view').hidden=view!=='review';$('#brief-view').hidden=view!=='brief';$('#breadcrumb-title').textContent=view==='review'?'Scope review':'Change brief';
 $('#nav-review').classList.toggle('active',view==='review');$('#nav-brief').classList.toggle('active',view==='brief');
 document.querySelectorAll('.tab').forEach(b=>b.classList.toggle('active',b.dataset.filter===filter));
}
function card(r){
 const label=r.override||r.result.label,open=expanded.has(r.id),done=r.result.source==='model';
 return `<article class="request-card" data-id="${r.id}"><div class="card-top"><span class="request-id">REQUEST ${String(r.id+1).padStart(2,'0')}</span><span class="badge ${label}">${LABELS[label]}</span></div><h3>${esc(r.text)}</h3><div class="card-source"><span class="avatar">${esc((project.client||'C').slice(0,1))}</span>${isSample?'Sample client request':'Your entered request'}</div><div class="card-bottom"><span class="card-state"><span class="model-dot">${done?'✳':'○'}</span>${r.override?'Your decision':done?'Local model reviewed':r.result.source==='rule'?'Safety check · AI skipped':'Waiting for your review'}</span><button class="review-toggle" aria-expanded="${open}" data-action="toggle">${open?'Close review':'Review request'} <span>${open?'−':'↗'}</span></button></div>${open?`<div class="details"><p class="reason">${esc(r.result.reason)}</p>${r.result.evidence.map(i=>`<div class="evidence"><span>RELATED SCOPE · S${String(i+1).padStart(2,'0')}</span><p>“${esc(project.scope[i])}”</p>${r.result.scores[i]?`<div class="score-row"><span>Support ${(r.result.scores[i].entailment*100).toFixed(1)}%</span><span>Conflict ${(r.result.scores[i].contradiction*100).toFixed(1)}%</span><span>Neutral ${(r.result.scores[i].neutral*100).toFixed(1)}%</span></div>`:''}</div>`).join('')}${done?'<p class="score-note">NLI scores describe text relations, not the chance work is contractually covered. All scope items were compared.</p>':''}<div class="review-form"><div class="form-row"><label>Your decision<select data-field="override" aria-label="Your decision for request ${r.id+1}"><option value="">Keep suggestion</option>${Object.entries(LABELS).map(([key,v])=>`<option value="${key}" ${r.override===key?'selected':''}>${v}</option>`).join('')}</select></label><label>Your estimated hours<input data-field="hours" type="number" min="0" max="10000" step="0.25" placeholder="Not estimated" value="${r.hours??''}" aria-label="Estimated hours for request ${r.id+1}"></label></div><label>Notes for the conversation<textarea data-field="notes" maxlength="2000" placeholder="What should you and the client confirm?" aria-label="Notes for request ${r.id+1}">${esc(r.notes)}</textarea></label><p class="manual-note">You can override any suggestion. Hours are included in totals only for possible changes.</p></div></div>`:''}</article>`;
}
$('#request-list').addEventListener('click',e=>{const b=e.target.closest('[data-action="toggle"]');if(!b)return;const id=Number(b.closest('[data-id]').dataset.id);expanded.has(id)?expanded.delete(id):expanded.add(id);render();document.querySelector(`[data-id="${id}"] .review-toggle`)?.focus();});
$('#request-list').addEventListener('change',e=>{const key=e.target.dataset.field;if(!key)return;responseDraft=null;const id=Number(e.target.closest('[data-id]').dataset.id),r=records.find(r=>r.id===id);if(key==='hours'){if(!e.target.checkValidity()){e.target.reportValidity();return;}r.hours=e.target.value===''?null:Number(e.target.value);}else r[key]=e.target.value;if(key!=='notes')render();else{$('#brief-output').textContent=makeBrief(project,records);$('#response-output').value=responseDraft??makeResponse(project,records);}});
$('#request-list').addEventListener('input',e=>{if(e.target.dataset.field==='notes'){responseDraft=null;const r=records.find(r=>r.id===Number(e.target.closest('[data-id]').dataset.id));r.notes=e.target.value;}});
function openEditor(blank=false){if(blank){$('#project-name').value='';$('#client-name').value='';$('#scope-input').value='';$('#requests-input').value='';}else{$('#project-name').value=project.title;$('#client-name').value=project.client;$('#scope-input').value=project.scope.join('\n');$('#requests-input').value=project.requests.join('\n');}$('#rate-input').value=project.rate;$('#currency-input').value=project.currency;$('#editor-error').textContent='';$('#editor-dialog').dataset.blank=String(blank);$('#editor-dialog').showModal();}
['#edit-project','#edit-requests','#edit-scope'].forEach(s=>$(s).addEventListener('click',()=>openEditor()));$('#start-blank').addEventListener('click',()=>openEditor(true));
$('#editor-form').addEventListener('submit',e=>{e.preventDefault();const scope=lines($('#scope-input').value),requests=lines($('#requests-input').value),error=validateInput(scope,requests);if(error){$('#editor-error').textContent=error;return;}responseDraft=null;const changed=JSON.stringify(scope)!==JSON.stringify(project.scope)||JSON.stringify(requests)!==JSON.stringify(project.requests);const wasBusy=busy;if(changed&&busy)cancelRun(false);project={title:$('#project-name').value.trim()||'Untitled project',client:$('#client-name').value.trim(),scope,requests,rate:Number($('#rate-input').value),currency:$('#currency-input').value};if(changed){resetRecords();status('Scope or requests changed. Previous analysis and review decisions were cleared.');if(wasBusy)status('Analysis canceled because your project changed. Previous review decisions were cleared.');}isSample=false;$('#editor-dialog').close();render();});
for(const s of ['download','editor','about','privacy'])$(`#${s}-dialog`).querySelectorAll('.dialog-close').forEach(b=>b.addEventListener('click',()=> $(`#${s}-dialog`).close()));
$('#about-open').addEventListener('click',()=>$('#about-dialog').showModal());$('#privacy-open').addEventListener('click',()=>$('#privacy-dialog').showModal());
$('#nav-review').addEventListener('click',()=>{view='review';render();});$('#nav-brief').addEventListener('click',()=>{view='brief';render();});
$('#open-brief').addEventListener('click',()=>{view='brief';render();window.scrollTo({top:0,behavior:'smooth'});});$('#back-review').addEventListener('click',()=>{view='review';render();});
$('#response-output').addEventListener('input',e=>{responseDraft=e.target.value;});
$('.tabs').addEventListener('click',e=>{const b=e.target.closest('[data-filter]');if(b){filter=b.dataset.filter;view='review';render();}});
$('#analyze').addEventListener('click',()=>{if(busy)return;const error=validateInput(project.scope,project.requests);if(error){status(error);openEditor();return;}if(!consented)$('#download-dialog').showModal();else analyze();});
$('#confirm-download').addEventListener('click',()=>{$('#download-dialog').close();consented=true;analyze();});
function setBusy(value){busy=value;$('#analyze').hidden=value;$('#cancel-run').hidden=!value;$('#progress-wrap').hidden=!value;}
function idleBanner(title,description,button){$('#model-title').textContent=title;$('#model-description').textContent=description;$('#analyze').textContent=button;}
function cancelRun(announce=true){runId++;worker?.terminate();worker=null;modelReady=false;clearTimeout(modelTimer);setBusy(false);idleBanner('Your review is still here.','The worker stopped. You can restart local analysis when you are ready.','Retry local analysis ↗');if(announce)status('Analysis canceled. No partial model results were applied. Your existing review is unchanged.');}
$('#cancel-run').addEventListener('click',()=>cancelRun());
function failRun(message){runId++;worker?.terminate();worker=null;modelReady=false;clearTimeout(modelTimer);setBusy(false);idleBanner('Local AI could not complete this review.','You can retry, or keep reviewing and exporting manually.','Retry local analysis ↗');status(message+' No new model results were applied.');}
function analyze(){
 setBusy(true);status('');const thisRun=++runId;$('#model-title').textContent=modelReady?'Comparing every scope item…':'Loading your private second opinion…';$('#model-description').textContent='Your scope and requests stay in this browser. You can cancel at any time.';$('#model-progress').removeAttribute('value');$('#progress-label').textContent='Preparing runtime…';
 try{if(!worker)worker=new Worker(new URL('./model-worker.js',import.meta.url),{type:'module'});}catch{failRun('The local model worker could not be created. Check your browser support, then retry.');return;}
 const handle=worker;worker.onerror=()=>{if(busy&&handle===worker&&thisRun===runId)failRun('The local model worker failed to start. Check your connection or browser support, then retry.');};
 clearTimeout(modelTimer);modelTimer=setTimeout(()=>{if(busy&&thisRun===runId)failRun('The model took too long to respond. A download, memory, or browser limitation may be blocking it.');},240000);
 worker.onmessage=e=>{const msg=e.data;if(handle!==worker||msg.runId!==runId)return;if(msg.type==='progress'){if(Number.isFinite(msg.percent))$('#model-progress').value=msg.percent;else $('#model-progress').removeAttribute('value');$('#progress-label').textContent=msg.text;}else if(msg.type==='ready'){modelReady=true;$('#model-title').textContent='Comparing requests with original scope…';}else if(msg.type==='error')failRun(msg.message);else if(msg.type==='complete'){clearTimeout(modelTimer);setBusy(false);records=records.map((r,i)=>({...r,result:msg.results[i]}));expanded.add(0);idleBanner('Review complete. Your judgment comes next.','Open each request to inspect the original evidence and make your decision.','Run review again ↗');const skipped=msg.results.filter(r=>r.source!=='model').length;status(`${msg.results.length-skipped} request${msg.results.length-skipped===1?'':'s'} compared by the local model${skipped?`; ${skipped} held for manual clarification`:''}. Existing manual decisions and estimates are preserved.`);render();}};
 worker.postMessage({type:'analyze',runId:thisRun,scope:project.scope,requests:project.requests});
}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('Copied. Review it before sending.');}catch{status('Clipboard access is unavailable. Select the text to copy it, or download the brief.');}}
$('#copy-brief').addEventListener('click',()=>copy(makeBrief(project,records)));$('#copy-response').addEventListener('click',()=>copy($('#response-output').value));
$('#download-brief').addEventListener('click',()=>{const blob=new Blob([makeBrief(project,records)],{type:'text/plain;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=(project.title||'scopecheck').toLowerCase().replace(/[^a-z0-9]+/g,'-')+'-scope-review.txt';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Brief downloaded to your device.');});
window.addEventListener('beforeunload',e=>{if(!isSample){e.preventDefault();e.returnValue='';}});
render();
